{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-x8jYvM/src/address.js","content":"// Address / column helpers.

// Convert column letters ("A".."ZZ") to a 1-based column number using
// bijective base-26 (A=1 ... Z=26, AA=27 ... ZZ=702).
export function colLettersToNum(letters) {
  let n = 0
  for (const ch of letters) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

// Reverse of colLettersToNum.
export function numToColLetters(num) {
  let n = num
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

// Split a word (already known to match /^[A-Za-z]+[0-9]*$/) into its
// letters run and digits run. Returns null if the word has no digits at
// all is fine (digits === ''), but if the shape does not match at all
// (should not happen given the lexer), returns null.
export function splitWord(word) {
  const m = /^([A-Za-z]+)([0-9]*)$/.exec(word)
  if (!m) return null
  return { letters: m[1].toUpperCase(), digits: m[2] }
}

// Determine whether a word (already uppercased) is a valid address in the
// addressable range: 1 or 2 letters, 1 to 3 digits, row >= 1.
export function parseValidAddress(word) {
  const m = /^([A-Z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  return { colLetters: m[1], row }
}

export function canonicalAddress(colLetters, row) {
  return colLetters + String(row)
}
"}

