const COMPARE_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const FUNCTION_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

// Parses formula source text (without the leading '=') into an AST, or
// returns null if the grammar does not accept the text.
export function parseFormula(src) {
  const tokens = tokenize(src)
  if (tokens === null) return null
  const state = { tokens, pos: 0 }
  const node = parseComparison(state)
  if (node === null) return null
  if (peek(state).t !== 'EOF') return null
  return node
}

function peek(state) {
  return state.tokens[state.pos]
}

function next(state) {
  return state.tokens[state.pos++]
}

function parseComparison(state) {
  let left = parseAdditive(state)
  if (left === null) return null
  for (;;) {
    const tok = peek(state)
    if (tok.t === 'OP' && COMPARE_OPS.has(tok.v)) {
      next(state)
      const right = parseAdditive(state)
      if (right === null) return null
      left = { type: 'bin', op: tok.v, left, right }
      continue
    }
    break
  }
  return left
}

function parseAdditive(state) {
  let left = parseMultiplicative(state)
  if (left === null) return null
  for (;;) {
    const tok = peek(state)
    if (tok.t === 'OP' && (tok.v === '+' || tok.v === '-')) {
      next(state)
      const right = parseMultiplicative(state)
      if (right === null) return null
      left = { type: 'bin', op: tok.v, left, right }
      continue
    }
    break
  }
  return left
}

function parseMultiplicative(state) {
  let left = parsePower(state)
  if (left === null) return null
  for (;;) {
    const tok = peek(state)
    if (tok.t === 'OP' && (tok.v === '*' || tok.v === '/')) {
      next(state)
      const right = parsePower(state)
      if (right === null) return null
      left = { type: 'bin', op: tok.v, left, right }
      continue
    }
    break
  }
  return left
}

function parsePower(state) {
  const left = parseUnary(state)
  if (left === null) return null
  const tok = peek(state)
  if (tok.t === 'OP' && tok.v === '^') {
    next(state)
    const right = parsePower(state)
    if (right === null) return null
    return { type: 'pow', base: left, exp: right }
  }
  return left
}

function parseUnary(state) {
  const tok = peek(state)
  if (tok.t === 'OP' && (tok.v === '+' || tok.v === '-')) {
    next(state)
    const operand = parseUnary(state)
    if (operand === null) return null
    return { type: 'unary', op: tok.v, operand }
  }
  return parsePrimary(state)
}

function parsePrimary(state) {
  const tok = peek(state)
  if (tok.t === 'NUM') {
    next(state)
    return { type: 'num', value: tok.v }
  }
  if (tok.t === 'LP') {
    next(state)
    const inner = parseComparison(state)
    if (inner === null) return null
    if (peek(state).t !== 'RP') return null
    next(state)
    return inner
  }
  if (tok.t === 'WORD') {
    const word = tok.v
    next(state)
    if (word === 'TRUE' || word === 'FALSE') {
      return { type: 'bool', value: word === 'TRUE' }
    }
    if (peek(state).t === 'LP') {
      next(state)
      const args = []
      if (peek(state).t === 'RP') {
        next(state)
      } else {
        for (;;) {
          const arg = parseComparison(state)
          if (arg === null) return null
