    super(`line ${line}: ${message}`)
    this.line = line
  }
}

// Parses the whole sheet text into a Map from canonical address ("A1") to
// {address, colLetters, row, content, line}. Throws SheetError on the
// first malformed line.
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const rawLine = lines[idx]

    let j = 0
    while (j < rawLine.length && (rawLine[j] === ' ' || rawLine[j] === '\t')) j++
    const rest = rawLine.slice(j)
    if (rest.length === 0 || rest[0] === '#') continue

    let k = 0
    while (k < rest.length && rest[k] !== ' ' && rest[k] !== '\t') k++
    const rawAddr = rest.slice(0, k)
    const addrUpper = rawAddr.toUpperCase()

    const shape = parseValidAddress(addrUpper)
    if (!shape) {
      throw new SheetError(lineNo, `invalid cell address ${addrUpper}`)
    }

    let m = k
    while (m < rest.length && (rest[m] === ' ' || rest[m] === '\t')) m++
    const content = rest.slice(m)

    const canon = canonicalAddress(shape.colLetters, shape.row)
    if (cells.has(canon)) {
      throw new SheetError(lineNo, `cell ${addrUpper} is declared twice`)
    }

    cells.set(canon, {
      address: canon,
      colLetters: shape.colLetters,
      row: shape.row,
      content,
      line: lineNo,
    })
  }

  return cells
}

// Returns the declared cells' canonical addresses in print order: ascending
// column number, then ascending row.
export function sortedAddresses(cells) {
  return Array.from(cells.values())
    .sort((a, b) => {
      const ca = colLettersToNum(a.colLetters)
      const cb = colLettersToNum(b.colLetters)
      if (ca !== cb) return ca - cb
      return a.row - b.row
    })
    .map((c) => c.address)
}
"}

