{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-x8jYvM/src/evaluator.js","content":"import { parseValidAddress, canonicalAddress, colLettersToNum, numToColLetters } from './address.js'
import { parseFormula } from './parser.js'

const LITERAL_NUMBER_RE = /^-?[0-9]+(\.[0-9]+)?$/
const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

const ERR = { t: 'error', v: '#ERR!' }
const REF = { t: 'error', v: '#REF!' }
const NAME_ERR = { t: 'error', v: '#NAME?' }
const DIV0 = { t: 'error', v: '#DIV/0!' }
const VALUE_ERR = { t: 'error', v: '#VALUE!' }
const CYCLE = { t: 'error', v: '#CYCLE!' }

export class Evaluator {
  constructor(cells) {
    this.cells = cells // Map canon -> {content, ...}
    this.cache = new Map() // canon -> Value
    this.visiting = new Set()
  }

  getCellValue(addr) {
    if (this.cache.has(addr)) return this.cache.get(addr)
    if (!this.cells.has(addr)) {
      const v = { t: 'number', v: 0 }
      this.cache.set(addr, v)
      return v
    }
    if (this.visiting.has(addr)) {
      return CYCLE
    }
    this.visiting.add(addr)
    const cell = this.cells.get(addr)
    let result
    if (cell.content.startsWith('=')) {
      const ast = parseFormula(cell.content.slice(1))
      if (ast === null) {
        result = ERR
      } else {
        result = this.evaluateScalar(ast)
      }
    } else {
      result = evaluateLiteral(cell.content)
    }
    this.visiting.delete(addr)
    this.cache.set(addr, result)
    return result
  }

  evaluateScalar(node) {
    switch (node.type) {
      case 'num':
        return { t: 'number', v: parseFloat(node.value) }
      case 'bool':
        return { t: 'bool', v: node.value }
      case 'range':
        return ERR
      case 'address': {
        const shape = parseValidAddress(node.word)
        if (!shape) return REF
        return this.getCellValue(canonicalAddress(shape.colLetters, shape.row))
      }
      case 'unary': {
        const operand = this.evaluateScalar(node.operand)
        const n = toNumber(operand)
        if (n.t === 'error') return n
        const val = node.op === '-' ? -n.v : n.v
        return finiteOrErr(val)
      }
      case 'pow': {
        const base = this.evaluateScalar(node.base)
        if (base.t === 'error') return base
        const exp = this.evaluateScalar(node.exp)
        if (exp.t === 'error') return exp
        const bn = toNumber(base)
        if (bn.t === 'error') return bn
        const en = toNumber(exp)
        if (en.t === 'error') return en
        return finiteOrErr(Math.pow(bn.v, en.v))
      }
      case 'bin': {
        const left = this.evaluateScalar(node.left)
        if (left.t === 'error') return left
        const right = this.evaluateScalar(node.right)
        if (right.t === 'error') return right
        if (isCompareOp(node.op)) {
          return compareOp(node.op, left, right)
        }
        return arithOp(node.op, left, right)
      }
      case 'call':
        return this.evaluateCall(node)
      default:
        return ERR
    }
  }

  expandArg(node) {
    if (node.type === 'range') return this.expandRangeNode(node)
    return [this.evaluateScalar(node)]
  }

  expandArgs(nodes) {
    let out = []
    for (const n of nodes) out = out.concat(this.expandArg(n))
    return out
  }

  expandRangeNode(node) {
    const left = parseValidAddress(node.left)
    const right = parseValidAddress(node.right)
    if (!left || !right) return [REF]
    const c1 = colLettersToNum(left.colLetters)
    const c2 = colLettersToNum(right.colLetters)
    const minCol = Math.min(c1, c2)
    const maxCol = Math.max(c1, c2)
    const minRow = Math.min(left.row, right.row)
    const maxRow = Math.max(left.row, right.row)
    const out = []
    for (let col = minCol; col <= maxCol; col++) {
      const colLetters = numToColLetters(col)
      for (let row = minRow; row <= maxRow; row++) {
        out.push(this.getCellValue(canonicalAddress(colLetters, row)))
      }
    }
    return out
  }

  evaluateCall(node) {
    const name = node.name
    const argNodes = node.args
    switch (name) {
      case 'SUM':
      case 'MIN':
      case 'MAX':
      case 'AVG':
      case 'COUNT': {
        if (argNodes.length < 1) return ERR
        const raw = this.expandArgs(argNodes)
        if (name === 'COUNT') {
          for (const v of raw) if (v.t === 'error') return v
          const cnt = raw.filter((v) => v.t === 'number').length
          return { t: 'number', v: cnt }
        }
        const nums = []
        for (const v of raw) {
          const c = toNumber(v)
          if (c.t === 'error') return c
          nums.push(c.v)
        }
        if (name === 'SUM') return finiteOrErr(nums.reduce((a, b) => a + b, 0))
        if (name === 'MIN') return finiteOrErr(Math.min(...nums))
        if (name === 'MAX') return finiteOrErr(Math.max(...nums))
        if (name === 'AVG') return finiteOrErr(nums.reduce((a, b) => a + b, 0) / nums.length)
        break
      }
      case 'ABS': {
        if (argNodes.length !== 1) return ERR
        const raw = this.expandArg(argNodes[0])
        let val
        for (const v of raw) {
          const c = toNumber(v)
          if (c.t === 'error') return c
          if (val === undefined) val = c.v
        }
        return finiteOrErr(Math.abs(val))
      }
      case 'IF': {
        if (argNodes.length !== 3) return ERR
        const rawCond = this.expandArg(argNodes[0])
        let condVal
        for (const v of rawCond) {
          if (v.t === 'error') return v
          if (condVal === undefined) condVal = v
        }
        let condBool
        if (condVal.t === 'bool') condBool = condVal.v
        else if (condVal.t === 'number') condBool = condVal.v !== 0
        else if (condVal.t === 'text') return VALUE_ERR
        const branchNode = condBool ? argNodes[1] : argNodes[2]
        const rawBranch = this.expandArg(branchNode)
        let result
        for (const v of rawBranch) {
          if (v.t === 'error') return v
          if (result === undefined) result = v
        }
        return result
      }
      default:
        return NAME_ERR
    }
    return ERR
  }
}

function evaluateLiteral(content) {
  if (content === '') return { t: 'number', v: 0 }
  if (LITERAL_NUMBER_RE.test(content)) return { t: 'number', v: parseFloat(content) }
  if (ERROR_TOKENS.has(content)) return { t: 'error', v: content }
  return { t: 'text', v: content }
}

function toNumber(value) {
  if (value.t === 'number') return value
  if (value.t === 'bool') return { t: 'number', v: value.v ? 1 : 0 }
  if (value.t === 'text') return VALUE_ERR
  return value // error
}

function finiteOrErr(x) {
  return Number.isFinite(x) ? { t: 'number', v: x } : DIV0
}

function isCompareOp(op) {
  return op === '=' || op === '<>' || op === '<' || op === '<=' || op === '>' || op === '>='
}

function rankOf(t) {
  if (t === 'number') return 0
  if (t === 'text') return 1
  return 2 // bool
}

function compareOp(op, left, right) {
  let cmp
  if (left.t !== right.t) {
    cmp = rankOf(left.t) - rankOf(right.t)
  } else if (left.t === 'number') {
    cmp = left.v - right.v
  } else if (left.t === 'text') {
    cmp = left.v < right.v ? -1 : left.v > right.v ? 1 : 0
  } else {
    // bool
    const lv = left.v ? 1 : 0
    const rv = right.v ? 1 : 0
    cmp = lv - rv
  }
  let result
  switch (op) {
    case '=':
      result = cmp === 0
      break
    case '<>':
      result = cmp !== 0
      break
    case '<':
      result = cmp < 0
      break
    case '<=':
      result = cmp <= 0
      break
    case '>':
      result = cmp > 0
      break
    case '>=':
      result = cmp >= 0
      break
    default:
      result = false
  }
  return { t: 'bool', v: result }
}

function arithOp(op, left, right) {
  const ln = toNumber(left)
  if (ln.t === 'error') return ln
  const rn = toNumber(right)
  if (rn.t === 'error') return rn
  let result
  switch (op) {
    case '+':
      result = ln.v + rn.v
      break
    case '-':
      result = ln.v - rn.v
      break
    case '*':
      result = ln.v * rn.v
      break
    case '/':
      result = ln.v / rn.v
      break
    default:
      result = NaN
  }
  return finiteOrErr(result)
}
"}

